// PlayServiceHandler is an implementation of the meurpg.play.v1.PlayService service.
type PlayServiceHandler interface {
	// StartGameSession opens the campaign's next game session. Only the
	// campaign's master may call it.
	//
	// In the same transaction, it locks the sheets of the campaign's player
	// characters that are alive and still drafts (RN-01): from then on, only
	// the master edits them. That includes characters created after an
	// earlier session, such as a replacement for a dead character: they lock
	// at the first session that starts after they were created. NPCs never
	// lock. It also ends every permission the master gave players to edit a
	// story (CharacterService.SetStoryEditing).
	//
	// A campaign has at most one open session. Not idempotent: calling it
	// again while the session is open fails with `failed_precondition`.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: the campaign already has an open session
	//     (GameSessionBlocked, SESSION_ALREADY_OPEN). End it first.
	StartGameSession(context.Context, *connect.Request[v1.StartGameSessionRequest]) (*connect.Response[v1.StartGameSessionResponse], error)
	// EndGameSession ends one of the campaign's game sessions. Only the
	// campaign's master may call it. Ending a session that already ended is
	// not an error: it returns the session as it is, with its first
	// ended_at. Ending a session never unlocks a sheet.
	//
	// Ending the open session sends `session_ended` on every
	// WatchGameSession stream of the campaign, which then ends.
	//
	// Errors:
	//   - `not_found`: the session is not in this campaign, the campaign does
	//     not exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	EndGameSession(context.Context, *connect.Request[v1.EndGameSessionRequest]) (*connect.Response[v1.EndGameSessionResponse], error)
	// ListGameSessions lists the campaign's game sessions, newest first. Any
	// member may call it. The list is not paginated.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	ListGameSessions(context.Context, *connect.Request[v1.ListGameSessionsRequest]) (*connect.Response[v1.ListGameSessionsResponse], error)
	// ListOpenGameSessions lists the open game sessions of every campaign the
	// caller is an active member of, as master or player, newest first. It is
	// the in-app notice that a session started (RN-06): the app calls it
	// about every 30 seconds while its tab is visible and the user is signed
	// in, and once when the tab comes back into view. A pending member
	// (RN-15) is not a member, so their campaigns never show up here. Anyone
	// signed in may call it; the list is not paginated.
	ListOpenGameSessions(context.Context, *connect.Request[v1.ListOpenGameSessionsRequest]) (*connect.Response[v1.ListOpenGameSessionsResponse], error)
	// GetLiveSession returns the campaign's open game session and the vitals
	// the caller may see (RN-02): the master gets every living player
	// character of the campaign (not the dead ones, nor one waiting for
	// approval); a player gets only their own living character, or none. It
	// is the live session's snapshot: the app reads it after
	// WatchGameSession's `ready` event, and again after every reconnection,
	// so a missed event never leaves the screen stale. It also names the
	// session's current map (SetCurrentMap), which the app reads with
	// meurpg.maps.v1.MapService.GetMap, and the image the master shows
	// (SetShownImage). Any member may call it.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it (a pending member neither). The app shows "Peça um
	//     convite ao mestre", without the campaign's name.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	GetLiveSession(context.Context, *connect.Request[v1.GetLiveSessionRequest]) (*connect.Response[v1.GetLiveSessionResponse], error)
	// WatchGameSession streams the live changes of the campaign's open game
	// session to one member (ADR-0005). Any member may call it.
	//
	// The first message is always `ready`, sent once the server has
	// subscribed the caller: only then does the app read the snapshot
	// (GetLiveSession), so no change falls between the snapshot and the
	// stream. A change can also arrive before the snapshot answers; the
	// vitals' `revision` tells which is newer. Then:
	//   - `heartbeat` every 25 seconds, so the app can tell a dead stream
	//     (nothing for about 60 seconds) and proxies don't close an idle one;
	//   - `vitals_changed` when the master corrects a character's vitals,
	//     sent only to the master and to that character's player;
	//   - `current_map_changed` when the master sets the session's current
	//     map, or it is deleted; sent to everyone;
	//   - `map_changed` when something the member sees on a map changed (a
	//     point, a token's state, the map's name, image or revealed state);
	//     the app reads the map again (MapService.GetMap). A player gets it
	//     only when the change touches something they see, before or after
	//     it (RN-10): a change to hidden things reaches only the master;
	//   - `token_moved` when the master moves a token: to everyone when the
	//     token is visible on a map the players see, only to the master
	//     otherwise;
	//   - `shown_image_changed` when the master shows an image, stops showing
	//     it, or deletes it; sent to everyone;
	//   - `left_images_changed` when the list of images left with the players
	//     changed (an image left, taken back or deleted); sent to everyone;
	//   - `encounter_changed` when anything changes in the combat; a hint,
	//     sent to everyone, and the app reads the combat again
	//     (CombatService.GetEncounter);
	//   - `turn_changed` when the turn passes: the round and who is on turn,
	//     as each member may see it (a player sees a hidden combatant's turn
	//     as the master's);
	//   - `combatant_moved` when a combatant moves on the grid: to the master
	//     always, and to a player only for a combatant they may see;
	//   - `combat_log_changed` when a line of the combat log appeared, changed
	//     or went away; a hint, and the app reads the log again
	//     (CombatService.ListCombatLog). The master gets every one; a player
	//     only those that touch a line they may see;
	//   - `session_ended` when the master ends the session; the stream then
	//     ends without an error.
	//
	// About every 60 seconds the server checks again, in the database, that
	// the caller is still signed in and still a member: if not, the stream
	// ends with the same error a call would get (`unauthenticated` or
	// `not_found`). A stream lasts at most 30 minutes and then ends without
	// an error; it also ends without an error when the server restarts. A
	// stream that cannot keep up (the app stopped reading) ends with
	// `unavailable`.
	//
	// The app reconnects after any end that is not an error below, with
	// backoff (1 s, 2 s, 4 s, up to 30 s, with jitter), and only while the
	// tab is visible; after each reconnection it reads the snapshot again.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it (a pending member neither).
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	WatchGameSession(context.Context, *connect.Request[v1.WatchGameSessionRequest], *connect.ServerStream[v1.WatchGameSessionResponse]) error
	// AdjustCharacterVitals is the master's correction of a player
	// character's vitals during the session (RN-02: the master has the final
	// word). Only the campaign's master may call it, and only while the
	// campaign has an open session. The character must be a living player
	// character of the campaign.
	//
	// Each value set in the request replaces the current one; unset values
	// stay as they are. At least one must be set. The change and a
	// session_events row are written together, then `vitals_changed` goes to
	// the master's and the character's player's streams.
	//
	// The class and race resources' used counts (resources_used: Retomar o
	// fôlego, Surto de ação...) are corrected here too: the app counts a use
	// when the combat spends it and the master brings it back (rests come
	// later). Healing a character above 0 hit points also resets the death
	// saves of its combatant in the session's combat (RN-03), and a character
	// set to 0 is "Caído" there.
	//
	// Calling again with the same idempotency_key (a retry) changes nothing
	// and returns the character's current vitals.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, the caller is not a
	//     member of it, or the character is not a living player character of
	//     the campaign (an NPC, a dead character, one waiting for approval).
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	//   - `invalid_argument`: nothing to change, an idempotency_key that is
	//     not a UUID or was already used for another character, or a value
	//     outside 0 to its maximum. The message names the field, such as
	//     `spell_slots_used[0].used`.
	AdjustCharacterVitals(context.Context, *connect.Request[v1.AdjustCharacterVitalsRequest]) (*connect.Response[v1.AdjustCharacterVitalsResponse], error)
	// SetCurrentMap chooses the map the session shows at the table, or clears
	// it. Only the campaign's master may call it, and only while the campaign
	// has an open session. The map must be one of the campaign's
	// (meurpg.maps.v1.MapService), and setting it also reveals it to the
	// players (RN-10): a player always sees the current map. Setting the same
	// map again is fine.
	//
	// Every WatchGameSession stream of the campaign then gets
	// `current_map_changed`, and GetLiveSession returns the new map. A new
	// session starts without a current map.
	//
	// Errors:
	//   - `not_found`: the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	SetCurrentMap(context.Context, *connect.Request[v1.SetCurrentMapRequest]) (*connect.Response[v1.SetCurrentMapResponse], error)
	// SetShownImage shows the players an image of the campaign's gallery, or
	// stops showing it (MR-028): a handout, such as a portrait, a letter or a
	// scene. Only the campaign's master may call it, and only while the
	// campaign has an open session. One image at a time; showing another
	// replaces it. It is apart from the current map: the players may see
	// both.
	//
	// It reveals nothing else: a player learns the image's ID only while it
	// is shown (GetLiveSession, `shown_image_changed`), never the gallery.
	// Every WatchGameSession stream of the campaign gets
	// `shown_image_changed`. A new session starts showing nothing; deleting
	// the image (GalleryService.DeleteGalleryImage) stops showing it.
	//
	// `keep` is the "Deixar com os jogadores" switch of the image shown. With
	// it on, when the master stops showing the image, shows another one or
	// ends the session, the image is left with the players
	// (ListLeftImages) instead of being taken away, and the streams get
	// `left_images_changed`. The master sets it by calling again with the
	// same image_id and the new `keep`, which sends no event: the players
	// never learn the switch. It is off for every image newly shown unless
	// the call says otherwise.
	//
	// Errors:
	//   - `not_found`: the image is not in the campaign's gallery, the
	//     campaign does not exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	SetShownImage(context.Context, *connect.Request[v1.SetShownImageRequest]) (*connect.Response[v1.SetShownImageResponse], error)
	// ListLeftImages returns the images the master left with the players
	// (SetShownImage's `keep`), in the order they were left. Any active
	// member may call it, in or out of a session: the left images belong to
	// the campaign, not to a session. They stay until the master takes them
	// back (TakeBackLeftImage), also after the session ends, so the list
	// lives in the campaign (campaign_left_images) and not in the session,
	// which would take the images away from the players when it ends. A
	// player gets their files (GET /images/{id}) while the image is on this
	// list (RN-10).
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it (a pending member neither).
	ListLeftImages(context.Context, *connect.Request[v1.ListLeftImagesRequest]) (*connect.Response[v1.ListLeftImagesResponse], error)
	// TakeBackLeftImage takes an image back from the players ("Tirar"): it
	// leaves the list, and the players can no longer fetch it. The image
	// stays in the gallery. Only the campaign's master may call it, in or out
	// of a session. Every WatchGameSession stream of the campaign gets
	// `left_images_changed`. Taking back an image that is not on the list is
	// `not_found`, so a second call (another tab) says so.
	//
	// Errors:
	//   - `not_found`: the image is not on the campaign's left list, the
	//     campaign does not exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	TakeBackLeftImage(context.Context, *connect.Request[v1.TakeBackLeftImageRequest]) (*connect.Response[v1.TakeBackLeftImageResponse], error)
	// OpenScene opens an RP scene in the session (MR-015, D7): the master
	// picks a SCENE point of the campaign's maps and every member sees it,
	// live, with the point's name and description and its actions, if it has
	// any (a scene with no actions opens too, question 63); each player with
	// their own character's bonus (GetOpenScene). The master also gets the
	// point's hooks and clues. Only the campaign's master may call it, and
	// only while the campaign has an open session. One scene at a time:
	// opening another replaces the first. The point may be hidden: opening it
	// reveals nothing, it stays hidden on the map (RN-10), but the group has
	// now "discovered" the scene (MR-030). Opening the scene that is already
	// open changes nothing; closing it and opening it again starts the rolls
	// afresh. Every stream gets `scene_changed`, and a `scene_opened` event
	// goes to the history.
	//
	// Errors:
	//   - `not_found`: the point is not a SCENE point of the campaign's maps,
	//     the campaign does not exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	OpenScene(context.Context, *connect.Request[v1.OpenSceneRequest]) (*connect.Response[v1.OpenSceneResponse], error)
	// CloseScene closes the open scene, asking nothing. Only the campaign's
	// master may call it. With no scene open it changes nothing. Every stream
	// gets `scene_changed`, and a `scene_closed` event goes to the history.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	CloseScene(context.Context, *connect.Request[v1.CloseSceneRequest]) (*connect.Response[v1.CloseSceneResponse], error)
	// GetOpenScene returns the scene open in the session, and the rolls made
	// in it, newest first (the scene log, MR-015). Any member may call it; the
	// app reads it after `ready` and after every `scene_changed` and
	// `scene_check_rolled`. What each one gets (RN-20):
	//   - the master: the actions with their DCs, and every roll with whether
	//     it passed;
	//   - a player: the actions without a DC, each with their own living
	//     character's bonus and passive value, and only their own rolls,
	//     with no pass or fail.
	// The scene is unset when none is open.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	GetOpenScene(context.Context, *connect.Request[v1.GetOpenSceneRequest]) (*connect.Response[v1.GetOpenSceneResponse], error)
	// RollSceneCheck rolls an action of the open scene for the caller's own
	// living character (MR-015, RN-18): the d20 plus the character's bonus
	// from the sheet. The server rolls the d20, or takes the face of a real
	// die (1 to 20), as the campaign's dice setting allows. A character rolls
	// each action once while the scene is open; the master closes and opens the
	// scene again for another roll. The answer is the roll with its total: the
	// DC, and whether it passed, stay with the master. The master gets
	// `scene_check_rolled` on the stream, and so does the roller; nobody else
	// does. A `scene_check_rolled` event goes to the history (ids and numbers
	// only). Only a player may call it.
	//
	// Errors:
	//   - `invalid_argument`: neither roll_in_app nor d20_face is set;
	//     roll_in_app is false; d20_face is not 1 to 20; the idempotency key
	//     is not a UUID.
	//   - `not_found`: the action is not one of the open scene's, the campaign
	//     does not exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is the master.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION); or SceneBlocked: NO_OPEN_SCENE, ALREADY_ROLLED,
	//     WRONG_DICE_MODE, NO_CHARACTER.
	RollSceneCheck(context.Context, *connect.Request[v1.RollSceneCheckRequest]) (*connect.Response[v1.RollSceneCheckResponse], error)
	// PutOnStage puts an NPC "em cena" (MR-031, D7): its name and portrait
	// appear to every member under the open scene, after the NPCs already
	// there. Only the campaign's master may call it, and only while a scene is
	// open. Any living NPC of the campaign will do, hidden in a combat or not
	// (putting it on stage reveals nothing in the combat). At most 4 NPCs are
	// on the stage at once. An NPC that is on the stage already changes
	// nothing. Every stream gets `stage_changed`, and a `stage_changed` event
	// goes to the history (ids only).
	//
	// Errors:
	//   - `not_found`: the character is not a living NPC of the campaign (or
	//     character_id is not a UUID), the campaign does not exist, or the
	//     caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION); or SceneBlocked: NO_OPEN_SCENE, STAGE_FULL.
	PutOnStage(context.Context, *connect.Request[v1.PutOnStageRequest]) (*connect.Response[v1.PutOnStageResponse], error)
	// TakeOffStage takes an NPC off the stage at once. An NPC that is not on
	// it changes nothing. Only the campaign's master may call it, and only
	// while the session is open (the stage is empty without a scene). Every
	// stream gets `stage_changed`.
	//
	// Errors:
	//   - `not_found`: character_id is not a UUID, the campaign does not exist,
	//     or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	TakeOffStage(context.Context, *connect.Request[v1.TakeOffStageRequest]) (*connect.Response[v1.TakeOffStageResponse], error)
	// SetSpeaker marks which NPC on the stage is speaking, or none (an empty
	// character_id). One at most: marking another takes the mark off the
	// first. Marking the one that already speaks changes nothing. Only the
	// campaign's master may call it. Every stream gets `stage_changed`.
	//
	// Errors:
	//   - `not_found`: the NPC is not on the stage (or character_id is set and
	//     is not a UUID), the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `failed_precondition`: no open session (GameSessionBlocked,
	//     NO_OPEN_SESSION).
	SetSpeaker(context.Context, *connect.Request[v1.SetSpeakerRequest]) (*connect.Response[v1.SetSpeakerResponse], error)
}

